sys_script_fix.script:
(function() {
    var gr = new GlideRecord('x_1947064_autoca_0_repair_plan');
    gr.query();

    var total = 0;
    var vehicleRef = 0;
    var inspectionRef = 0;
    var appointmentRef = 0;

    while (gr.next()) {
        total++;

        if (!gr.vehicle_ref.nil())
            vehicleRef++;

        if (!gr.inspection_ref.nil())
            inspectionRef++;

        if (!gr.appointment_ref.nil())
            appointmentRef++;
    }

    gs.info(
        'AUTOCARE REPAIR PLAN CHECK' +
        ' | TOTAL=' + total +
        ' | VEHICLE_REF=' + vehicleRef +
        ' | INSPECTION_REF=' + inspectionRef +
        ' | APPOINTMENT_REF=' + appointmentRef
    );

})();
